// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Toggle as TogglePrimitive } from "radix-ui";
import { cn } from "./utils";
const toggleVariants = cva("roc-ui roc-ui-toggle", {
  variants: {
    variant: {
      default: "roc-ui-toggle-default",
      outline: "roc-ui-toggle-outline",
    },
    size: {
      default: "roc-ui-toggle-default-size",
      sm: "roc-ui-toggle-sm",
      lg: "roc-ui-toggle-lg",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});
function Toggle({
  className,
  variant,
  size,
  ...props
}: React.ComponentProps<typeof TogglePrimitive.Root> &
  VariantProps<typeof toggleVariants>) {
  return (
    <TogglePrimitive.Root
      data-slot="toggle"
      className={cn(toggleVariants({ variant, size }), className)}
      {...props}
    />
  );
}
export { Toggle, toggleVariants };

import "./toggle.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-ui-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 36px;
  min-height: 36px;
  padding: 7px 10px;
  border: 1px solid transparent;
  border-radius: var(--roc-radius, 8px);
  background: transparent;
  font-weight: 500;
  line-height: 1.2;
  cursor: pointer;
  transition:
    background-color 160ms,
    color 160ms;
}
.roc-ui-toggle-outline {
  border-color: var(--roc-line, #dedede);
}
.roc-ui-toggle:hover:not(:disabled) {
  background: var(--roc-marker, #eee);
}
.roc-ui-toggle[data-state="on"] {
  background: var(--roc-ink, #252525);
  color: var(--roc-paper, #fff);
}
.roc-ui-toggle-sm {
  min-width: 32px;
  min-height: 32px;
  padding: 5px 8px;
}
.roc-ui-toggle-lg {
  min-width: 42px;
  min-height: 42px;
  padding: 10px 14px;
}
@media (pointer: coarse) {
  .roc-ui-toggle {
    min-width: 44px;
    min-height: 44px;
  }
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
@keyframes roc-ui-reveal {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}
